      // KS-1101: a 2xx whose body reports `status: 'degraded'` is degraded, not healthy.
      if (reported.status === 'degraded') {
        return { status: 'degraded', latency, version, ...(reported.degradedReasons !== undefined ? { degradedReasons: reported.degradedReasons } : {}) };
      }
      return { status: 'healthy', latency, version };
    }

    return { status: 'unhealthy', latency };
  } catch (error) {
    return {
      status: 'unreachable',
      latency: Date.now() - start,
      error: error instanceof Error ? error.message : 'Unknown error',
    };
  }
}

function checkDependency(dep: DependencyDefinition): {
  status: 'configured' | 'missing' | 'invalid';
  value?: string;
} {
  if (dep.checkMethod === 'env' && dep.envVar) {
    const value = process.env[dep.envVar];
    if (!value) {
      return { status: 'missing' };
    }
    // Mask sensitive values
    const masked = value.length > 8 
      ? `${value.substring(0, 4)}...${value.substring(value.length - 4)}`
      : '****';
    return { status: 'configured', value: masked };
  }
  return { status: 'missing' };
}

function getNodeVersion(): string {
  try {
    return process.version;
  } catch {
    return 'unknown';
  }
}

function getNpmVersion(): string {
  try {
    return execSync('npm --version', { encoding: 'utf-8' }).trim();
  } catch {
    return 'unknown';
  }
}

